const canvas=document.getElementById("chart"),ctx=canvas.getContext("2d");
function rand(seed){let x=Math.sin(seed++)*10000;return x-Math.floor(x)}
function getData(c){
 let n=172,a=[],v=c.start;
 for(let i=0;i<n;i++){
   let wave=Math.sin(i*.18+c.seed)*.25+Math.sin(i*.047+c.seed)*.6;
   let event=0;
   if(c===configs.VIX && i>90&&i<110) event=rand(i+7)*25;
   if(c===configs.DJI && i>88&&i<103) event=-rand(i+3)*500;
   if(c===configs.NDQ && i>88&&i<103) event=-rand(i+3)*700;
   v += c.trend*(c.max-c.min)/5 + wave*(c.max-c.min)/100 + event;
   v=Math.max(c.min+.03*(c.max-c.min),Math.min(c.max-.03*(c.max-c.min),v));
   let scale=(c.max-c.min)/70, o=v+(rand(i+c.seed)-.5)*scale*2;
