   a.push({o,cl,hi,lo});
 }
 return a;
}
function draw(){
 const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;
 canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0);
