 ctx.clearRect(0,0,w,h);ctx.fillStyle="#fff";ctx.fillRect(0,0,w,h);
 const left=8,right=76,top=26,bottom=82, cw=w-left-right,ch=h-top-bottom;
 ctx.strokeStyle="#edf0f2";ctx.lineWidth=1;
 let rows=10,cols=12;
 for(let i=0;i<=rows;i++){let y=top+ch*i/rows;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(left+cw,y);ctx.stroke()}
 for(let i=0;i<=cols;i++){let x=left+cw*i/cols;ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,top+ch);ctx.stroke()}
 const range=c.max-c.min;
 ctx.font="12px Arial";ctx.fillStyle="#555";ctx.textAlign="left";
 for(let i=0;i<=rows;i++){let val=c.max-range*i/rows,y=top+ch*i/rows+4;ctx.fillText(format(val,current),left+cw+10,y)}
 ctx.textAlign="center";ctx.fillStyle="#555";
 let months=["Oct","Nov","Dec","2025","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep"];
 for(let i=0;i<months.length;i++)ctx.fillText(months[i],left+cw*i/(months.length-1),top+ch+29);
 let step=cw/data.length, bw=Math.max(3,step*.58);
 data.forEach((q,i)=>{
   let x=left+i*step+step/2;
   let y=v=>top+(c.max-v)/range*ch;
   ctx.strokeStyle=q.cl>=q.o?"#129c79":"#dd2850";ctx.lineWidth=1;
