   ctx.fillStyle=q.cl>=q.o?"#159b78":"#dc2850";
   let yy=Math.min(y(q.o),y(q.cl)), hh=Math.max(1,Math.abs(y(q.o)-y(q.cl)));
   ctx.fillRect(x-bw/2,yy,bw,hh);
 });
 // current line
 let currentVal=parseFloat(c.price.replace(",",""));
 let cy=top+(c.max-currentVal)/range*ch;
 ctx.setLineDash([2,3]);ctx.strokeStyle="#84c8b7";ctx.beginPath();ctx.moveTo(left,cy);ctx.lineTo(left+cw,cy);ctx.stroke();ctx.setLineDash([]);
 ctx.fillStyle="#19a17e";ctx.fillRect(left+cw,cy-10,right,20);ctx.fillStyle="#fff";ctx.textAlign="center";ctx.font="12px Arial";ctx.fillText(c.price,left+cw+right/2,cy+4);
 ctx.strokeStyle="#d4d8db";ctx.beginPath();ctx.moveTo(left+cw+1,top);ctx.lineTo(left+cw+1,top+ch);ctx.stroke();
}
